{
  "claims": [
    {
      "agent": "NOC",
      "type": "action",
      "verb": "rollback_change",
      "params": {
        "ticket": "CHG-1",
        "site": "core site A",
        "restore": "previous configuration snapshot"
      },
      "inject_refs": ["S1-I1", "S1-I2"],
      "rationale": "The auto-approved change lowered the route-flood protection limit and removed the inbound route filter, causing core site A isolation and loss of emergency-call routing. Immediate rollback is the safest restoration step.",
      "evidence": [
        {
          "chunk_id": "US-FCC-ATT-2024-REPORT#0001",
          "quote": "AT&T Mobility implemented a network change with an equipment configuration error on Thursday, February 22, 2024 at 2:42 AM. Just three minutes later, the nationwide outage began."
        },
        {
          "chunk_id": "UK-OFCOM-BT-999-2024#0000",
          "quote": "Phase 1, from 06:24 to 07:33 – During the first hour, BT’s emergency call handling system was disrupted by what was later found to be a configuration error in a file on its server."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "alt_auth_route",
      "params": {
        "region": "R2",
        "destination": "999 centre",
        "via": "core site B"
      },
      "inject_refs": ["S1-I2"],
      "rationale": "Emergency-call routing for R2 has no path while core site B is healthy with spare capacity; rerouting restores 999 connectivity and reduces public harm.",
      "evidence": [
        {
          "chunk_id": "AU-ACMA-TELSTRA-2024#0000",
          "quote": "The investigation found Telstra initiated a contingency process to transfer calls received during the disruption, using a list of backup phone numbers."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "action",
      "verb": "enable_review_queue",
      "params": {
        "target": "closed-loop network optimiser",
        "policy": "require human review and sandbox before production changes"
      },
      "inject_refs": ["S1-I1"],
      "rationale": "The optimiser auto-approved a change and skipped the sandbox stage, showing lack of human oversight; enabling a review queue prevents recurrence of unsafe automated changes.",
      "evidence": [
        {
          "chunk_id": "ITU-T-Y3172#0037",
          "quote": "NOTE – The sandbox subsystem is not shown for simplicity in Figure I.1, but its functionality is applicable also to Figure I.1."
        }
      ]
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must notify the regulator (TDRA) of the unplanned outage within two hours of discovering it.",
      "inject_refs": ["S1-I2", "S1-I6"],
      "rationale": "Global best practice and major-outage reporting rules require prompt regulatory notification to enable oversight and public protection.",
      "evidence": [
        {
          "chunk_id": "CA-CRTC-2025-225#0023",
          "quote": "The two-hour notification timeframe established in the interim measure has proven sufficient to keep the Commission and ISED informed while allowing the TSPs to focus their efforts on restoring services during the earliest hours of an outage."
        }
      ],
      "deadline_hours": 2
    },
    {
      "agent": "NOC",
      "type": "obligation",
      "statement": "NOC must notify the emergency call centre (PSAP/999 centre) of the outage affecting emergency calls within 30 minutes of becoming aware.",
      "inject_refs": ["S1-I2", "S1-I3"],
      "rationale": "Emergency services are directly affected; timely PSAP notification enables activation of contingency measures and public alerts.",
      "evidence": [
        {
          "chunk_id": "CA-CRTC-2025-225#0032",
          "quote": "For major 9-1-1 service outages: 9-1-1 network providers and originating network providers must notify (i) PSAPs within 30 minutes; and (ii) the Commission, ISED, and FPT EMOs within two hours."
        }
      ],
      "deadline_hours": 0.5
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "open_incident",
      "params": {
        "incident_type": "unplanned outage",
        "region": "R2",
        "severity": "major"
      },
      "inject_refs": ["S1-I6"],
      "rationale": "A journalist inquiry and evidence of emergency-call failure indicate a major incident; TDRA should formally open an incident to coordinate regulatory response.",
      "evidence": [
        {
          "chunk_id": "UK-OFCOM-BT-999-2024#0000",
          "quote": "On 28 June 2023 Ofcom opened an investigation to establish whether the company had failed to comply with its legal duties to take appropriate and proportionate measures to prepare for potential disruption to its network."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "action",
      "verb": "request_report",
      "params": {
        "recipient": "OpCo",
        "content": "initial and final outage reports including root cause, timeline, impact, and restoration actions"
      },
      "inject_refs": ["S1-I6", "S1-I7"],
      "rationale": "TDRA needs a formal report from the operator to assess compliance, public safety impact, and necessary enforcement or remedial measures.",
      "evidence": [
        {
          "chunk_id": "US-CFR-47-4-9#0004",
          "quote": "Not later than 72 hours after discovering the outage, the provider(s) shall submit electronically an Initial Communications Outage Report to the Commission."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_deadline",
      "statement": "No UAE-specific regulatory deadline is evidenced for operators to notify TDRA of unplanned outages, causing uncertainty at T+40 when the duty officer questions the required timeframe.",
      "inject_refs": ["S1-I7"],
      "rationale": "The internal question reveals that the operator's licence may not specify notification hours, unlike global precedents that set 2-hour notifications.",
      "evidence": [
        {
          "chunk_id": "CA-CRTC-2025-225#0023",
          "quote": "The two-hour notification timeframe established in the interim measure has proven sufficient to keep the Commission and ISED informed while allowing the TSPs to focus their efforts on restoring services during the earliest hours of an outage."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-CFR-47-4-9#0004",
          "quote": "shall submit electronically a Notification to the Commission within 120 minutes of discovering such outage."
        }
      ]
    },
    {
      "agent": "REG",
      "type": "gap",
      "gap_type": "no_rule",
      "statement": "No regulatory rule requires sandbox testing or human review before AI-driven network changes that can affect emergency services, as evidenced by the auto-approved, sandbox-skipped change CHG-1.",
      "inject_refs": ["S1-I1"],
      "rationale": "The optimiser changed a critical core parameter without sandbox validation or human approval, creating a foreseeable risk; regulation is needed to mandate such safeguards.",
      "evidence": [
        {
          "chunk_id": "ITU-T-Y3172#0037",
          "quote": "NOTE – The sandbox subsystem is not shown for simplicity in Figure I.1, but its functionality is applicable also to Figure I.1."
        }
      ],
      "global_examples": [
        {
          "chunk_id": "US-FCC-ATT-2024-REPORT#0001",
          "quote": "AT&T Mobility implemented a network change with an equipment configuration error on Thursday, February 22, 2024 at 2:42 AM. Just three minutes later, the nationwide outage began."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "assess_transfer",
      "params": {
        "transfer": "bulk upload of subscriber-level data to cloud region outside UAE",
        "requestor": "network vendor",
        "data_elements": ["MSISDN", "IMSI"]
      },
      "inject_refs": ["S1-I4", "S1-I5"],
      "rationale": "Full core logs with subscriber identifiers must not be transferred offshore without legal basis; DPA should assess the lawfulness and safeguards before any export occurs.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication."
        }
      ]
    },
    {
      "agent": "DPA",
      "type": "action",
      "verb": "open_investigation",
      "params": {
        "subject": "scheduled bulk upload of subscriber-level data to cloud region outside UAE",
        "source": "national monitoring flag"
      },
      "inject_refs": ["S1-I5"],
      "rationale": "The flagged upload suggests a potential unauthorised cross-border transfer; DPA should investigate to determine if data protection rules were breached.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication."
        }
      ]
    },
    {
      "agent": "CSC",
      "type": "action",
      "verb": "notify",
      "params": {
        "recipient": "DPA",
        "event": "S1-I5 scheduled bulk upload of subscriber-level data outside UAE"
      },
      "inject_refs": ["S1-I5"],
      "rationale": "CSC has visibility of the flagged upload and must immediately inform DPA to enable regulatory intervention and prevent potential data exposure.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-CBUAE-OTP-2025#0000",
          "quote": "The regulator said OTPs should not be shared through weak modes of communication."
        }
      ]
    },
    {
      "agent": "CSC",
      "type": "action",
      "verb": "issue_advisory",
      "params": {
        "audience": "customers in region R2",
        "content": "service outage affecting calls, including 999; alternative emergency contact methods"
      },
      "inject_refs": ["S1-I3"],
      "rationale": "Customers are experiencing call failures and public concern is rising; an official advisory mitigates confusion and directs users to alternative channels.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-DU-OUTAGE-2026#0000",
          "quote": "Du has carried out a planned system update to improve network performance. Call services are now fully restored and operating normally."
        }
      ]
    },
    {
      "agent": "EMS",
      "type": "action",
      "verb": "activate_alt_channels",
      "params": {
        "region": "R2",
        "channels": ["SMS", "mobile app", "alternative voice route"]
      },
      "inject_refs": ["S1-I3"],
      "rationale": "Voice calls to 999 are failing; emergency services must activate alternative contact channels to ensure the public can reach help.",
      "evidence": [
        {
          "chunk_id": "AU-ACMA-TELSTRA-2024#0000",
          "quote": "The investigation found Telstra initiated a contingency process to transfer calls received during the disruption, using a list of backup phone numbers."
        }
      ]
    },
    {
      "agent": "EMS",
      "type": "action",
      "verb": "public_alert",
      "params": {
        "region": "R2",
        "message": "999 calls are failing; use alternative channels (SMS, app) until service is restored."
      },
      "inject_refs": ["S1-I3"],
      "rationale": "Social media reports indicate public uncertainty; an official public alert from emergency services reduces risk and provides actionable guidance.",
      "evidence": [
        {
          "chunk_id": "UAE-PRESS-DU-OUTAGE-2026#0000",
          "quote": "Du has carried out a planned system update to improve network performance. Call services are now fully restored and operating normally."
        }
      ]
    }
  ]
}
